package kr.co.donationserver.client;
import kr.co.donationserver.client.gui.*;import kr.co.donationserver.network.*;import net.minecraft.client.Minecraft;import net.minecraftforge.fml.common.network.simpleimpl.*;
public final class ClientPacketHandlers {private ClientPacketHandlers(){}public static class Open implements IMessageHandler<PacketOpenGui,IMessage>{public IMessage onMessage(PacketOpenGui m,MessageContext c){Minecraft.getMinecraft().addScheduledTask(()->Minecraft.getMinecraft().displayGuiScreen(new GuiFastTravel()));return null;}}public static class Sync implements IMessageHandler<PacketSync,IMessage>{public IMessage onMessage(PacketSync m,MessageContext c){Minecraft.getMinecraft().addScheduledTask(()->{ClientState.balance=m.balance;ClientState.personal=m.personal;ClientState.total=m.total;});return null;}}public static class OpenShop implements IMessageHandler<PacketOpenShop,IMessage>{public IMessage onMessage(PacketOpenShop m,MessageContext c){Minecraft.getMinecraft().addScheduledTask(()->Minecraft.getMinecraft().displayGuiScreen(new GuiNpcShop(m)));return null;}}}
